# //TR: Bu script evidence private key dosyasını Windows'ta current user + SYSTEM dışındaki inherited ACL'lerden ayırmaya çalışır; başarısızsa Phase0 evidence-key protection PASS vermez.
$ErrorActionPreference="Stop";Set-Location (Split-Path -Parent $PSScriptRoot);$p=".ai\runtime\keys\evidence-ed25519-private.pem";if(-not(Test-Path $p)){throw "Evidence private key missing"};if($IsWindows -or $env:OS -eq "Windows_NT"){& icacls $p /inheritance:r | Out-Null;& icacls $p /grant:r "${env:USERNAME}:(R,W)" "SYSTEM:(F)" | Out-Null;if($LASTEXITCODE -ne 0){throw "Evidence key ACL hardening failed"}};@{"//TR"="Bu runtime report evidence private key filesystem permission hardening sonucunu taşır.";status="PASS";checkedAt=(Get-Date).ToString("o")}|ConvertTo-Json|Set-Content -Encoding UTF8 ".ai\runtime\EVIDENCE_KEY_PROTECTION.json";Write-Host "EVIDENCE_KEY_PROTECTION: PASS"
